mapper.select:
select mn.*, u.U_NAME as initiatingPersonName,c.C_NAME as initiatingUnitName
from construction_drawing mn
left join sys_user u on u.U_ID = mn.Initiating_Person
left join sys_company c on c.C_ID = mn.Initiating_Unit
${params.authSql}

    and mn.id = #{params.id}


    and mn.Initiating_Person = #{params.initiatingPerson}


    and mn.Initiating_Unit = #{params.initiatingUnit}


    and u.U_NAME like concat('%', #{params.initiatingPersonName}, '%')


    and c.C_NAME like concat('%', #{params.initiatingUnitName}, '%')


    and mn.state = #{params.state}


    and mn.Initiating_Person_Phone like concat('%', #{params.initiatingPersonPhone}, '%')


    and mn.Construction_Drawing_Code like concat('%', #{params.constructionDrawingCode}, '%')


    and mn.Create_Time between #{params.createTimeRange[0]} and #{params.createTimeRange[1]}


    and mn.id not in (select distinct
    mr.Mr_Report_Construction_Drawing_Id from maintenance_record mr where mr.Mr_State!=3)


    and mn.Construction_Drawing_Name like concat('%', #{params.constructionDrawingName}, '%')

order by mn.Create_Time desc
